-- Integración aditiva. Ejecutar con psql -v ON_ERROR_STOP=1.
BEGIN;
ALTER TABLE roles ADD COLUMN IF NOT EXISTS descripcion TEXT NOT NULL DEFAULT '';
ALTER TABLE roles ADD COLUMN IF NOT EXISTS permisos JSONB;
ALTER TABLE roles ADD COLUMN IF NOT EXISTS acciones JSONB;
ALTER TABLE usuarios ADD COLUMN IF NOT EXISTS estado VARCHAR(20) NOT NULL DEFAULT 'Activo';
UPDATE usuarios SET estado='Inactivo' WHERE NOT activo AND estado='Activo';
ALTER TABLE lote ADD COLUMN IF NOT EXISTS codigo VARCHAR(100);
CREATE UNIQUE INDEX IF NOT EXISTS uq_lote_codigo_web ON lote(lower(codigo)) WHERE codigo IS NOT NULL;
ALTER TABLE unidades ADD COLUMN IF NOT EXISTS id_usuario_registro INT REFERENCES usuarios(id_usuario);
ALTER TABLE cierresturno ADD COLUMN IF NOT EXISTS estado VARCHAR(20) NOT NULL DEFAULT 'Cerrado';
ALTER TABLE cierresturno ADD COLUMN IF NOT EXISTS nota TEXT NOT NULL DEFAULT '';
ALTER TABLE cierresturno ADD COLUMN IF NOT EXISTS origen_web BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE cierresturno ADD COLUMN IF NOT EXISTS revision INT NOT NULL DEFAULT 1;
ALTER TABLE cierresturno ADD COLUMN IF NOT EXISTS total_reportadas INT;
-- El índice parcial no modifica ni consolida los cierres históricos existentes.
CREATE UNIQUE INDEX IF NOT EXISTS uq_cierre_web ON cierresturno(id_linea,id_turno,(fecha::date)) WHERE origen_web;
ALTER TABLE autorizacion ADD COLUMN IF NOT EXISTS datos JSONB;
ALTER TABLE autorizacion ADD COLUMN IF NOT EXISTS motivo_resolucion TEXT;
CREATE TABLE IF NOT EXISTS incidencias_web (
 id_incidencia BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 id_usuario INT NOT NULL REFERENCES usuarios(id_usuario),
 id_linea INT NOT NULL REFERENCES linea(id_linea),
 tipo VARCHAR(30) NOT NULL, severidad VARCHAR(10) NOT NULL,
 paro INT NOT NULL CHECK(paro>=0), motivo TEXT NOT NULL,
 fecha TIMESTAMP NOT NULL DEFAULT (CURRENT_TIMESTAMP AT TIME ZONE 'America/Mexico_City')
);
CREATE TABLE IF NOT EXISTS ajustes_conteo_web (
 id_autorizacion INT PRIMARY KEY REFERENCES autorizacion(id_autorizacion),
 id_orden INT NOT NULL REFERENCES ordenes(id_orden),
 id_linea INT NOT NULL REFERENCES linea(id_linea),
 id_turno INT NOT NULL REFERENCES turnos(id_turno),
 fecha DATE NOT NULL, diferencia INT NOT NULL
);
CREATE TABLE IF NOT EXISTS catalogos_web (
 tipo VARCHAR(30) NOT NULL, codigo VARCHAR(100) NOT NULL, nombre VARCHAR(150) NOT NULL,
 activo BOOLEAN NOT NULL DEFAULT TRUE, id_original INT,
 PRIMARY KEY(tipo,codigo)
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_catalogo_codigo ON catalogos_web(tipo,lower(codigo));
CREATE UNIQUE INDEX IF NOT EXISTS uq_catalogo_original ON catalogos_web(tipo,id_original) WHERE id_original IS NOT NULL;
INSERT INTO catalogos_web(tipo,codigo,nombre,id_original)
 SELECT 'modelos',nombre,nombre,id_modelo FROM modelos ON CONFLICT DO NOTHING;
INSERT INTO catalogos_web(tipo,codigo,nombre,id_original)
 SELECT 'lineas','L'||id_linea,nombre,id_linea FROM linea ON CONFLICT DO NOTHING;
INSERT INTO catalogos_web(tipo,codigo,nombre,id_original)
 SELECT 'turnos',id_turno::text,'Turno '||id_turno,id_turno FROM turnos ON CONFLICT DO NOTHING;
INSERT INTO catalogos_web(tipo,codigo,nombre,id_original)
 SELECT 'clientes','C'||id_cliente,nombre,id_cliente FROM clientes ON CONFLICT DO NOTHING;
INSERT INTO catalogos_web(tipo,codigo,nombre,id_original)
 SELECT 'categorias','CAT'||id_categoria,nombre,id_categoria FROM cat_defectos ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS configuracion_web (
 clave TEXT PRIMARY KEY, valor JSONB NOT NULL,
 id_usuario INT REFERENCES usuarios(id_usuario),
 fecha TIMESTAMP NOT NULL DEFAULT (CURRENT_TIMESTAMP AT TIME ZONE 'America/Mexico_City'),
 motivo TEXT NOT NULL
);
INSERT INTO configuracion_web(clave,valor,motivo) VALUES
 ('capacidadCaja','{"NS-MINI":12,"NS-SPORT":8,"NS-PRO":6,"NS-MAX":4}', 'Capacidades iniciales del catálogo oficial')
 ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS tickets_web (
 id_ticket BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 num_empleado VARCHAR(50) NOT NULL, nombre VARCHAR(100) NOT NULL, motivo TEXT NOT NULL,
 estado VARCHAR(20) NOT NULL DEFAULT 'Abierto', comentarios TEXT NOT NULL DEFAULT '',
 fecha TIMESTAMP NOT NULL DEFAULT (CURRENT_TIMESTAMP AT TIME ZONE 'America/Mexico_City'),
 id_usuario_cierre INT REFERENCES usuarios(id_usuario), fecha_cierre TIMESTAMP
);
CREATE INDEX IF NOT EXISTS ix_unidades_fecha_linea_turno ON unidades(fecha_hora,id_linea,id_turno);
-- Los valores iniciales de permisos se agregan a continuación; no se sobrescriben cambios posteriores.

INSERT INTO roles(nombre) SELECT 'Operador' WHERE NOT EXISTS(SELECT 1 FROM roles WHERE nombre='Operador');
UPDATE roles SET descripcion='Consulta su orden y línea; registra producción o incidencias permitidas. No modifica cierres.',permisos='{"login/login": "acciona", "login/levantar-ticket": "acciona", "produccion/tablero-de-produccion-del-turno": "acciona", "produccion/registrar-produccion": "acciona", "produccion/registrar-incidencia": "acciona"}'::jsonb,acciones='["registrar-produccion"]'::jsonb WHERE nombre='Operador' AND permisos IS NULL;

INSERT INTO roles(nombre) SELECT 'Líder de línea' WHERE NOT EXISTS(SELECT 1 FROM roles WHERE nombre='Líder de línea');
UPDATE roles SET descripcion='Ve producción del turno, objetivos y diferencias; solicita ajustes y cierra el turno.',permisos='{"login/login": "acciona", "login/levantar-ticket": "acciona", "produccion/tablero-de-produccion-del-turno": "ver", "produccion/registrar-incidencia": "ver", "produccion/tablero-de-linea-lider": "acciona", "produccion/solicitar-ajuste": "acciona", "produccion/cierre-de-turno": "acciona"}'::jsonb,acciones='["solicitar-ajuste-de-produccion-o-de-cierre", "guardar-cierre-de-turno"]'::jsonb WHERE nombre='Líder de línea' AND permisos IS NULL;

INSERT INTO roles(nombre) SELECT 'Inspector de Calidad' WHERE NOT EXISTS(SELECT 1 FROM roles WHERE nombre='Inspector de Calidad');
UPDATE roles SET descripcion='Registra inspección, defecto y disposición; libera o retiene unidades.',permisos='{"login/login": "acciona", "login/levantar-ticket": "acciona"}'::jsonb,acciones='[]'::jsonb WHERE nombre='Inspector de Calidad' AND permisos IS NULL;

INSERT INTO roles(nombre) SELECT 'Almacén/Empaque' WHERE NOT EXISTS(SELECT 1 FROM roles WHERE nombre='Almacén/Empaque');
UPDATE roles SET descripcion='Crea cajas, agrega unidades liberadas, cierra cajas y prepara embarques.',permisos='{"login/login": "acciona", "login/levantar-ticket": "acciona", "empaque/inicio-de-empaque-panel-de-control": "acciona", "empaque/formar-caja": "acciona", "empaque/confirmar-cierre-de-caja": "acciona", "empaque/consultar-caja": "ver", "empaque/historial-de-cajas": "ver", "empaque/reportes-de-empaque": "ver", "embarques/armar-embarque": "acciona", "embarques/paquetes-en-embarcacion": "acciona", "embarques/cierre-de-caja-escaneo": "acciona", "embarques/confirmacion-de-cierre-de-caja": "acciona", "embarques/estado-del-embarque": "ver", "embarques/rastreo-de-contenedor": "ver", "embarques/grafica-de-embarques": "ver"}'::jsonb,acciones='["cerrar-caja", "confirmar-salida-de-embarque"]'::jsonb WHERE nombre='Almacén/Empaque' AND permisos IS NULL;

INSERT INTO roles(nombre) SELECT 'Subgerente de Producción' WHERE NOT EXISTS(SELECT 1 FROM roles WHERE nombre='Subgerente de Producción');
UPDATE roles SET descripcion='Consulta todas las líneas y órdenes; revisa avance y autoriza ajustes.',permisos='{"login/login": "acciona", "login/levantar-ticket": "acciona", "gerencia/dashboard": "ver", "gerencia/discrepancias": "ver", "gerencia/autorizaciones": "acciona", "gerencia/trazabilidad": "ver", "gerencia/cierres-de-turno": "ver"}'::jsonb,acciones='["aprobar-o-rechazar-ajustes-y-reaperturas"]'::jsonb WHERE nombre='Subgerente de Producción' AND permisos IS NULL;

INSERT INTO roles(nombre) SELECT 'Gerente de Producción' WHERE NOT EXISTS(SELECT 1 FROM roles WHERE nombre='Gerente de Producción');
UPDATE roles SET descripcion='Consulta indicadores, históricos y cierres; autoriza reaperturas de turno.',permisos='{"login/login": "acciona", "login/levantar-ticket": "acciona", "gerencia/dashboard": "ver", "gerencia/discrepancias": "ver", "gerencia/autorizaciones": "acciona", "gerencia/trazabilidad": "ver", "gerencia/cierres-de-turno": "ver"}'::jsonb,acciones='["aprobar-o-rechazar-ajustes-y-reaperturas"]'::jsonb WHERE nombre='Gerente de Producción' AND permisos IS NULL;

INSERT INTO roles(nombre) SELECT 'Gerente de Planta' WHERE NOT EXISTS(SELECT 1 FROM roles WHERE nombre='Gerente de Planta');
UPDATE roles SET descripcion='Consulta tableros, cumplimiento, defectos y embarques. No captura producción.',permisos='{"login/login": "acciona", "login/levantar-ticket": "acciona", "gerencia/dashboard": "ver", "gerencia/discrepancias": "ver", "gerencia/autorizaciones": "ver", "gerencia/trazabilidad": "ver", "gerencia/cierres-de-turno": "ver"}'::jsonb,acciones='[]'::jsonb WHERE nombre='Gerente de Planta' AND permisos IS NULL;

INSERT INTO roles(nombre) SELECT 'Administrador' WHERE NOT EXISTS(SELECT 1 FROM roles WHERE nombre='Administrador');
UPDATE roles SET descripcion='Administra el sistema y conserva el acceso operativo existente.',permisos='{"login/login": "acciona", "login/levantar-ticket": "acciona", "sistemas/area-de-tickets": "acciona", "sistemas/ver-ticket": "acciona", "sistemas/usuarios": "acciona", "sistemas/nuevo-o-editar-usuario": "acciona", "sistemas/roles-y-permisos": "acciona", "sistemas/catalogos": "acciona", "sistemas/parametros": "acciona", "produccion/tablero-de-produccion-del-turno": "acciona", "produccion/registrar-produccion": "acciona", "produccion/registrar-incidencia": "acciona", "produccion/tablero-de-linea-lider": "acciona", "produccion/solicitar-ajuste": "acciona", "produccion/cierre-de-turno": "acciona", "empaque/inicio-de-empaque-panel-de-control": "acciona", "empaque/formar-caja": "acciona", "empaque/confirmar-cierre-de-caja": "acciona", "empaque/consultar-caja": "acciona", "empaque/historial-de-cajas": "acciona", "empaque/reportes-de-empaque": "acciona", "embarques/armar-embarque": "acciona", "embarques/paquetes-en-embarcacion": "acciona", "embarques/cierre-de-caja-escaneo": "acciona", "embarques/confirmacion-de-cierre-de-caja": "acciona", "embarques/estado-del-embarque": "acciona", "embarques/rastreo-de-contenedor": "acciona", "embarques/grafica-de-embarques": "acciona", "gerencia/dashboard": "acciona", "gerencia/discrepancias": "acciona", "gerencia/autorizaciones": "acciona", "gerencia/trazabilidad": "acciona", "gerencia/cierres-de-turno": "acciona"}'::jsonb,acciones='["registrar-produccion", "solicitar-ajuste-de-produccion-o-de-cierre", "guardar-cierre-de-turno", "aprobar-o-rechazar-ajustes-y-reaperturas", "cerrar-caja", "reabrir-caja", "confirmar-salida-de-embarque", "administrar-usuarios-roles-catalogos-y-parametros"]'::jsonb WHERE nombre='Administrador' AND permisos IS NULL;

INSERT INTO roles(nombre) SELECT 'Supervisor de almacén' WHERE NOT EXISTS(SELECT 1 FROM roles WHERE nombre='Supervisor de almacén');
UPDATE roles SET descripcion='Reabre cajas cerradas (queda auditoría). Propuesto como 9.º rol (C9).',permisos='{"login/login": "acciona", "login/levantar-ticket": "acciona", "empaque/inicio-de-empaque-panel-de-control": "ver", "empaque/consultar-caja": "acciona", "empaque/historial-de-cajas": "ver", "empaque/reportes-de-empaque": "ver"}'::jsonb,acciones='["reabrir-caja"]'::jsonb WHERE nombre='Supervisor de almacén' AND permisos IS NULL;

UPDATE roles SET permisos='{}'::jsonb,acciones='[]'::jsonb WHERE permisos IS NULL;
COMMIT;
